import { useCallback } from "react";
export const useBodyScroll = () => {
    const resetScroll = useCallback(() => {
        document.body.classList.remove("zen-popup-body", "zen-popup-body--hidden");
    }, []);
    const setScrollHidden = useCallback(() => {
        document.body.classList.add("zen-popup-body", "zen-popup-body--hidden");
    }, []);
    return { setScrollHidden, resetScroll };
};
